// Booga Booga Track dashboard - Cloudflare Worker
// Serves the dashboard and proxies /api/* to your API (set API_URL in wrangler.toml or Worker variables).
const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Booga Booga Track</title>\n<style>\n:root{--bg:#07070c;--panel:rgba(255,255,255,.04);--panel2:rgba(255,255,255,.07);--bd:rgba(255,255,255,.09);--fg:#f5f5fa;--mute:#8d8da3;--ok:#34d399;--bad:#fb7185;--a1:#e4e4ee;--a2:#8d8da3;--r:18px}\nmain[data-tab=mojo]{--a1:#c4b5fd;--a2:#7c3aed}\nmain[data-tab=candy]{--a1:#fde68a;--a2:#f97316}\nmain[data-tab=inventory]{--a1:#5eead4;--a2:#0ea5e9}\nmain[data-tab=overview]{--a1:#c4b5fd;--a2:#f97316}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml,body{min-height:100%;background:var(--bg);color:var(--fg);font-family:\"Inter\",system-ui,-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif;-webkit-font-smoothing:antialiased}\nbutton,input,select{font:inherit;color:inherit}\n.bg{position:fixed;inset:0;z-index:-1;background:radial-gradient(900px 500px at 8% -10%,rgba(124,58,237,.28),transparent 60%),radial-gradient(800px 500px at 100% 110%,rgba(249,115,22,.18),transparent 60%),var(--bg)}\n.app{display:flex;min-height:100vh}\naside{width:268px;flex:none;position:sticky;top:0;height:100vh;padding:22px 16px 18px;display:flex;flex-direction:column;border-right:1px solid var(--bd);background:rgba(10,10,16,.6);backdrop-filter:blur(14px)}\n.logo{display:flex;align-items:center;gap:12px;padding:2px 8px 22px}\n.logo .mark{width:42px;height:42px;border-radius:13px;display:grid;place-items:center;background:linear-gradient(135deg,rgba(124,58,237,.45),rgba(249,115,22,.35));border:1px solid var(--bd)}\n.logo .mark img{width:26px;height:26px;object-fit:contain}\n.logo b{display:block;font-size:17px;letter-spacing:-.2px}\n.logo small{color:var(--mute);font-size:11px;letter-spacing:2px;text-transform:uppercase}\n.grp{font-size:11px;letter-spacing:1.6px;color:var(--mute);text-transform:uppercase;padding:14px 12px 6px}\nnav button{width:100%;display:flex;align-items:center;gap:12px;background:none;border:0;cursor:pointer;text-align:left;padding:10px 12px;border-radius:12px;font-size:15px;color:#c5c5d6;position:relative;transition:background .15s,color .15s}\nnav button:hover{background:var(--panel);color:#fff}\nnav button.active{background:linear-gradient(90deg,rgba(255,255,255,.10),rgba(255,255,255,.03));color:#fff}\nnav button.active::before{content:\"\";position:absolute;left:-16px;top:9px;bottom:9px;width:3px;border-radius:0 3px 3px 0;background:linear-gradient(#c4b5fd,#f97316)}\nnav .ic{width:26px;height:26px;display:grid;place-items:center;flex:none}\nnav .ic img{width:26px;height:26px;object-fit:contain}\nnav .ic svg{width:21px;height:21px}\nnav .tag{margin-left:auto;font-size:12px;color:var(--mute);background:var(--panel);padding:2px 8px;border-radius:20px}\n.side-bot{margin-top:auto;display:flex;flex-direction:column;gap:12px}\n.status{display:flex;align-items:center;gap:10px;padding:12px 14px;border:1px solid var(--bd);border-radius:14px;background:var(--panel);font-size:14px}\n.dot{width:9px;height:9px;border-radius:50%;background:#555;flex:none}\n.dot.on{background:var(--ok);box-shadow:0 0 10px var(--ok)}\n.loader{display:flex;align-items:center;justify-content:center;gap:10px;border:0;cursor:pointer;padding:13px 16px;border-radius:14px;font-weight:600;font-size:15px;color:#0a0a10;background:linear-gradient(135deg,#c4b5fd,#fdba74);transition:transform .15s,box-shadow .15s;box-shadow:0 8px 24px -10px rgba(196,181,253,.7)}\n.loader:hover{transform:translateY(-1px);box-shadow:0 12px 28px -10px rgba(253,186,116,.8)}\n.loader svg{width:20px;height:20px}\nmain{flex:1;min-width:0;padding:30px 36px 56px;max-width:1260px;margin:0 auto;animation:fade .35s ease}\n@keyframes fade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}\n.top{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:24px}\nh1{font-size:30px;letter-spacing:-.6px;font-weight:700}\n.sub{color:var(--mute);margin-top:4px;font-size:15px}\n.live{display:flex;align-items:center;gap:8px;color:var(--mute);font-size:13px;border:1px solid var(--bd);padding:7px 13px;border-radius:30px;background:var(--panel);white-space:nowrap}\n.pulse{width:8px;height:8px;border-radius:50%;background:var(--ok);animation:pl 1.6s infinite}\n@keyframes pl{0%{box-shadow:0 0 0 0 rgba(52,211,153,.6)}100%{box-shadow:0 0 0 9px rgba(52,211,153,0)}}\n.msg{display:none;margin-bottom:18px;border:1px solid rgba(251,113,133,.35);background:rgba(251,113,133,.08);color:#fecdd3;padding:12px 16px;border-radius:12px;font-size:14px}\n.msg.show{display:block}\n.card{background:var(--panel);border:1px solid var(--bd);border-radius:var(--r);padding:20px;backdrop-filter:blur(8px)}\n.card h3{font-size:15px;font-weight:600;margin-bottom:14px;display:flex;align-items:center;justify-content:space-between}\n.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:16px}\n.stat{display:flex;flex-direction:column;gap:6px;position:relative;overflow:hidden}\n.stat .chip{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:var(--panel2);margin-bottom:6px}\n.stat .chip img{width:24px;height:24px;object-fit:contain}.stat .chip svg{width:20px;height:20px}\n.stat .l{color:var(--mute);font-size:13px}\n.stat .v{font-size:28px;font-weight:700;letter-spacing:-.5px}\n.stat .d{font-size:13px;color:var(--mute)}\n.stat .d b{color:var(--ok);font-weight:600}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}\n.earnhead{display:flex;align-items:center;gap:14px;margin-bottom:6px}\n.earnhead .big{font-size:34px;font-weight:800;letter-spacing:-1px;background:linear-gradient(90deg,var(--a1),#fff);-webkit-background-clip:text;background-clip:text;color:transparent}\n.earnhead .lbl{color:var(--mute);font-size:14px}\n.hero{margin-bottom:16px}\n.hero-top{display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap;align-items:flex-start}\n.hero-l{display:flex;align-items:center;gap:20px}\n.hero-ic{width:92px;height:68px;color:var(--a1);flex:none;filter:drop-shadow(0 0 18px var(--a2))}\n.hero .big{font-size:48px;font-weight:800;letter-spacing:-1.6px;line-height:1;background:linear-gradient(90deg,var(--a1),#fff);-webkit-background-clip:text;background-clip:text;color:transparent}\n.hero .lbl{font-size:18px;font-weight:600;margin-top:6px}\n.ctl{display:flex;gap:10px;flex-wrap:wrap;align-items:center}\n.pills{display:flex;background:var(--panel);border:1px solid var(--bd);border-radius:30px;padding:3px}\n.pills button{background:none;border:0;border-radius:26px;padding:6px 16px;cursor:pointer;font-size:13px;color:var(--mute)}\n.pills button.active{background:var(--panel2);color:#fff}\nselect,.fld{background:var(--panel);border:1px solid var(--bd);border-radius:12px;padding:9px 14px;font-size:14px;outline:none;color:var(--fg)}\nselect option{background:#14141c}\nselect:focus,.fld:focus{border-color:rgba(255,255,255,.35)}\n.minis{display:flex;gap:26px;margin-top:18px;flex-wrap:wrap}\n.minis div{display:flex;flex-direction:column;gap:2px}.minis small{color:var(--mute);font-size:12px}.minis b{font-size:18px}\n.chart{position:relative;margin-top:12px}\n.chart svg{width:100%;height:auto;display:block;overflow:visible}\n.tip{position:absolute;pointer-events:none;transform:translate(-50%,-110%);background:#14141d;border:1px solid var(--bd);border-radius:10px;padding:6px 10px;font-size:12px;white-space:nowrap;opacity:0;transition:opacity .1s;box-shadow:0 8px 24px rgba(0,0,0,.5)}\n.tip b{display:block;font-size:14px}\n.lb{display:flex;flex-direction:column}\n.lrow{display:grid;grid-template-columns:40px minmax(120px,1.2fr) 2fr auto auto;align-items:center;gap:14px;padding:11px 0;border-bottom:1px solid var(--bd)}\n.lrow:last-child{border-bottom:0}\n.av{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;font-weight:700;font-size:15px;color:#fff;position:relative}\n.av i{position:absolute;right:-3px;bottom:-3px;width:11px;height:11px;border-radius:50%;background:#555;border:2px solid #0d0d14}\n.av i.on{background:var(--ok)}\n.nm{display:flex;flex-direction:column;min-width:0}.nm b{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.nm small{color:var(--mute);font-size:12px}\n.bar{height:8px;background:var(--panel2);border-radius:8px;overflow:hidden}\n.bar i{display:block;height:100%;border-radius:8px;background:linear-gradient(90deg,var(--a2),var(--a1));transition:width .6s ease}\n.val{font-weight:700;font-size:17px;min-width:90px;text-align:right}\n.chip2{font-size:12px;padding:4px 10px;border-radius:20px;background:rgba(52,211,153,.12);color:var(--ok);min-width:86px;text-align:center}\n.lrow.off{opacity:.5}\n.lvl{font-size:11px;padding:1px 8px;border-radius:20px;border:1px solid var(--bd);color:var(--mute);margin-left:6px;font-weight:500}\n.empty{text-align:center;color:var(--mute);padding:34px 10px}\n.tool{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}.tool .fld{flex:1;min-width:200px}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:14px}\n.item{background:var(--panel);border:1px solid var(--bd);border-radius:16px;padding:16px 12px;display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center;transition:transform .15s,border-color .15s}\n.item:hover{transform:translateY(-3px);border-color:rgba(94,234,212,.5)}\n.item .ico{width:76px;height:76px;border-radius:18px;display:grid;place-items:center;background:radial-gradient(circle at 50% 35%,rgba(94,234,212,.22),rgba(255,255,255,.03) 70%);border:1px solid var(--bd)}\n.item .ico img{max-width:58px;max-height:58px}\n.item .ph{font-size:26px;font-weight:700;color:#5eead4}\n.item .n{font-size:14px;font-weight:600;word-break:break-word}\n.item .q{font-size:22px;font-weight:800;letter-spacing:-.5px}\n.chips{display:flex;gap:4px;flex-wrap:wrap;justify-content:center}\n.chips span{font-size:11px;color:var(--mute);background:var(--panel2);padding:2px 8px;border-radius:20px}\ntable{width:100%;border-collapse:collapse}\nth{font-size:12px;color:var(--mute);text-align:left;font-weight:500;padding:0 10px 10px;text-transform:uppercase;letter-spacing:.8px}\ntd{padding:12px 10px;border-top:1px solid var(--bd);font-size:15px;white-space:nowrap}\ntd.r,th.r{text-align:right}\n.who{display:flex;align-items:center;gap:12px}\n.pill{display:inline-flex;align-items:center;gap:6px;font-size:12px;padding:4px 10px;border-radius:20px;background:var(--panel2)}\n.pill.on{background:rgba(52,211,153,.12);color:var(--ok)}\n.btn{background:#fff;color:#000;border:0;border-radius:11px;padding:10px 18px;cursor:pointer;font-weight:600;font-size:14px}\n.btn.ghost{background:var(--panel);color:var(--fg);border:1px solid var(--bd)}\n.btn.sm{padding:6px 12px;font-size:12px}.btn.red{color:var(--bad)}\n.set{display:flex;flex-direction:column;gap:16px;max-width:760px}\n.set p{color:var(--mute);font-size:14px;margin-bottom:12px;line-height:1.5}\n.line{display:flex;gap:10px;flex-wrap:wrap;align-items:center}\n.line .fld{flex:1;min-width:220px}\n.opt{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:12px 0;border-top:1px solid var(--bd)}\n.opt:first-of-type{border-top:0}\n.opt span small{display:block;color:var(--mute);font-size:13px;margin-top:2px}\n.sw{position:relative;width:44px;height:25px;flex:none}.sw input{display:none}\n.sw i{position:absolute;inset:0;border-radius:25px;background:var(--panel2);border:1px solid var(--bd);cursor:pointer;transition:.2s}\n.sw i::after{content:\"\";position:absolute;left:3px;top:3px;width:17px;height:17px;border-radius:50%;background:#fff;transition:.2s}\n.sw input:checked+i{background:linear-gradient(135deg,#8b5cf6,#f97316)}.sw input:checked+i::after{left:22px}\ncode.box{display:block;background:#05050a;border:1px solid var(--bd);border-radius:12px;padding:14px;font-size:13px;color:#d6d6ff;overflow-x:auto;white-space:nowrap;margin-bottom:12px}\n.ok{color:var(--ok)}.bad{color:var(--bad)}\n.toast{position:fixed;left:50%;bottom:32px;transform:translate(-50%,20px);background:#fff;color:#000;padding:12px 22px;border-radius:30px;font-weight:600;opacity:0;pointer-events:none;transition:.28s;box-shadow:0 12px 40px rgba(0,0,0,.5)}\n.toast.show{opacity:1;transform:translate(-50%,0)}\n@media(max-width:1000px){.stats{grid-template-columns:repeat(2,1fr)}.two{grid-template-columns:1fr}}\n@media(max-width:820px){\n .app{flex-direction:column}\n aside{width:100%;height:auto;position:static;flex-direction:row;flex-wrap:wrap;align-items:center;padding:12px;gap:8px;border-right:0;border-bottom:1px solid var(--bd)}\n .logo{padding:0 8px 0 0}.logo small,.grp,.status,nav .tag{display:none}\n nav{display:flex;overflow-x:auto;order:3;width:100%}nav button{width:auto;white-space:nowrap;padding:8px 12px}\n nav button.active::before{display:none}\n .side-bot{margin:0 0 0 auto;flex-direction:row}.loader{padding:9px 12px;font-size:13px}\n main{padding:20px 14px 50px}h1{font-size:24px}\n .lrow{grid-template-columns:40px 1fr auto}.lrow .bar,.lrow .chip2{display:none}\n .hero .big{font-size:36px}.hero-ic{width:64px;height:48px}\n .stat .v{font-size:22px}.live{display:none}\n}\n</style>\n</head>\n<body>\n<div class=\"bg\"></div>\n<div class=\"app\">\n  <aside>\n    <div class=\"logo\"><div class=\"mark\"><img src=\"/icon-mojo.png\" alt=\"\"></div><div><b>Booga Booga</b><small>Track</small></div></div>\n    <nav id=\"nav\">\n      <div class=\"grp\">Track</div>\n      <button data-tab=\"overview\"><span class=\"ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"13.5\" y=\"3\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"3\" y=\"13.5\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"13.5\" y=\"13.5\" width=\"7.5\" height=\"7.5\" rx=\"2\"/></svg></span>Overview</button>\n      <button data-tab=\"mojo\"><span class=\"ic\"><img src=\"/icon-mojo.png\" alt=\"\"></span>Mojo</button>\n      <button data-tab=\"candy\"><span class=\"ic\"><img src=\"/icon-candy.png\" alt=\"\"></span>Candy</button>\n      <button data-tab=\"inventory\"><span class=\"ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><path d=\"M3 7.5 12 3l9 4.5v9L12 21l-9-4.5z\"/><path d=\"M3 7.5l9 4.5 9-4.5M12 12v9\"/></svg></span>Inventory</button>\n      <div class=\"grp\">Manage</div>\n      <button data-tab=\"accounts\"><span class=\"ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"9\" cy=\"8\" r=\"3.5\"/><path d=\"M2.5 20c.6-3.6 3.2-5.5 6.5-5.5s5.9 1.9 6.5 5.5\"/><path d=\"M16 4.6a3.5 3.5 0 0 1 0 6.8M18 14.8c2 .6 3.2 2.2 3.5 5.2\"/></svg></span>Accounts<span class=\"tag\" id=\"tagAcc\">0</span></button>\n      <button data-tab=\"settings\"><span class=\"ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3.2\"/><path d=\"M12 2.5v3M12 18.5v3M2.5 12h3M18.5 12h3M5.3 5.3l2.1 2.1M16.6 16.6l2.1 2.1M5.3 18.7l2.1-2.1M16.6 7.4l2.1-2.1\"/></svg></span>Settings</button>\n    </nav>\n    <div class=\"side-bot\">\n      <div class=\"status\"><span class=\"dot\" id=\"sdot\"></span><span id=\"stxt\">Not connected</span></div>\n      <button class=\"loader\" id=\"copyLoader\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 7 9 15a2.5 2.5 0 0 0 3.5 3.5L20 11a4.5 4.5 0 0 0-6.4-6.4L6 12a6.5 6.5 0 0 0 9.2 9.2L19 17.5\"/></svg>Copy loader</button>\n    </div>\n  </aside>\n  <main id=\"main\"></main>\n</div>\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\nwindow.__CFG__ = /*CFG*/{};\n(function(){\nconst CFG = window.__CFG__ || {};\nconst $ = s => document.querySelector(s);\nconst esc = s => String(s ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst ls = { get:(k,d)=>{try{const v=localStorage.getItem(k);return v===null?d:v}catch(e){return d}}, set:(k,v)=>{try{localStorage.setItem(k,v)}catch(e){}} };\nconst state = { tab: ls.get('bb_tab','overview'), key: ls.get('bb_key',''), range: 60, accounts: [], q: '', sort: 'qty', invUser: 'all', chartUser: 'all',\n  hideOffline: ls.get('bb_hide','0')==='1', compact: ls.get('bb_compact','0')==='1', interval: +ls.get('bb_int','5') };\nlet busy = false, timer = null;\n\nfunction fmt(n){ if (n == null) return '\u2014'; n = Math.round(n);\n  if (state.compact) { const a = Math.abs(n); for (const [v,s] of [[1e12,'T'],[1e9,'B'],[1e6,'M'],[1e3,'K']]) if (a >= v) return (n/v).toFixed(a>=v*100?0:a>=v*10?1:2).replace(/\\.0+$|(\\.\\d)0$/,'$1') + s; }\n  return n.toLocaleString('en-US'); }\nfunction ago(ms){ if(!ms) return 'never'; const s=Math.max(0,(Date.now()-ms)/1000|0); if(s<10) return 'just now'; if(s<60) return s+'s ago'; if(s<3600) return (s/60|0)+'m ago'; if(s<86400) return (s/3600|0)+'h ago'; return (s/86400|0)+'d ago'; }\nfunction toast(t){ const el=$('#toast'); el.textContent=t; el.classList.add('show'); clearTimeout(toast.t); toast.t=setTimeout(()=>el.classList.remove('show'),1900); }\nfunction msg(t){ const el=$('#msg'); if(!el) return; el.textContent=t||''; el.classList.toggle('show',!!t); }\nfunction setNum(sel, v, f){ const el = typeof sel==='string'?$(sel):sel; if(!el) return; f = f || fmt;\n  const from = el.dataset.v === undefined ? v : +el.dataset.v; el.dataset.v = v;\n  if (from === v) { el.textContent = f(v); return; }\n  const t0 = performance.now(); cancelAnimationFrame(el._r);\n  const step = t => { const k = Math.min(1,(t-t0)/700), e = 1-Math.pow(1-k,3); el.textContent = f(from+(v-from)*e); if (k<1) el._r=requestAnimationFrame(step); else el.textContent=f(v); };\n  el._r = requestAnimationFrame(step); }\nfunction hue(s){ let h=0; for (const c of String(s)) h=(h*31+c.charCodeAt(0))%360; return h; }\nfunction avatar(a){ const h=hue(a.user); return `<div class=\"av\" style=\"background:linear-gradient(135deg,hsl(${h} 70% 55%),hsl(${(h+50)%360} 70% 40%))\">${esc(a.user[0]||'?').toUpperCase()}<i class=\"${a.online?'on':''}\"></i></div>`; }\n\nasync function api(path, opts={}){\n  const r = await fetch(path, Object.assign({}, opts, { headers: Object.assign({'x-key': state.key}, opts.headers||{}) }));\n  if (r.status === 401) throw new Error('auth');\n  if (!r.ok) throw new Error('http ' + r.status);\n  return r.json();\n}\n\n/* ---------- charts ---------- */\nfunction niceCeil(m){ const p = Math.pow(10, Math.floor(Math.log10(m))); for (const k of [1,2,2.5,5,10]) if (m <= k*p) return k*p; return 10*p; }\nfunction chart(el, buckets, color, unit, id){\n  if (typeof el === 'string') el = $(el); if (!el) return;\n  const W = 800, H = 250, L = 50, R = 12, T = 14, B = 28, n = buckets.length;\n  const max = niceCeil(Math.max(1, ...buckets.map(b => b.earned)));\n  const X = i => L + i*(W-L-R)/(n-1), Y = v => T + (1 - v/max)*(H-T-B);\n  let line = `M${X(0)},${Y(buckets[0].earned)}`;\n  for (let i = 1; i < n; i++) { const mx = (X(i-1)+X(i))/2; line += ` C${mx},${Y(buckets[i-1].earned)} ${mx},${Y(buckets[i].earned)} ${X(i)},${Y(buckets[i].earned)}`; }\n  const area = line + ` L${X(n-1)},${H-B} L${X(0)},${H-B}Z`;\n  let grid = '';\n  for (let g = 0; g <= 4; g++) { const v = max*g/4, y = Y(v); grid += `<line x1=\"${L}\" x2=\"${W-R}\" y1=\"${y}\" y2=\"${y}\" stroke=\"rgba(255,255,255,.07)\"/><text x=\"${L-8}\" y=\"${y+4}\" fill=\"#8d8da3\" font-size=\"13\" text-anchor=\"end\">${fmtShort(v)}</text>`; }\n  const tl = i => new Date(buckets[i].t).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});\n  const xl = [0, (n/2)|0, n-1].map((i,k) => `<text x=\"${X(i)}\" y=\"${H-7}\" fill=\"#8d8da3\" font-size=\"13\" text-anchor=\"${k===0?'start':k===2?'end':'middle'}\">${tl(i)}</text>`).join('');\n  el.innerHTML = `<svg viewBox=\"0 0 ${W} ${H}\"><defs><linearGradient id=\"g${id}\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"${color}\" stop-opacity=\".45\"/><stop offset=\"1\" stop-color=\"${color}\" stop-opacity=\"0\"/></linearGradient></defs>\n    ${grid}<path d=\"${area}\" fill=\"url(#g${id})\"/><path d=\"${line}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>${xl}\n    <line class=\"vl\" y1=\"${T}\" y2=\"${H-B}\" stroke=\"rgba(255,255,255,.3)\" stroke-dasharray=\"4 4\" opacity=\"0\"/><circle class=\"pt\" r=\"5.5\" fill=\"#fff\" stroke=\"${color}\" stroke-width=\"3\" opacity=\"0\"/></svg><div class=\"tip\"></div>`;\n  const svg = el.querySelector('svg'), tip = el.querySelector('.tip'), vl = svg.querySelector('.vl'), pt = svg.querySelector('.pt');\n  el.onmousemove = e => { const r = svg.getBoundingClientRect(); const px = (e.clientX - r.left)/r.width*W;\n    const i = Math.max(0, Math.min(n-1, Math.round((px-L)/((W-L-R)/(n-1))))); const x = X(i), y = Y(buckets[i].earned);\n    vl.setAttribute('x1',x); vl.setAttribute('x2',x); vl.setAttribute('opacity',1); pt.setAttribute('cx',x); pt.setAttribute('cy',y); pt.setAttribute('opacity',1);\n    tip.innerHTML = `${tl(i)}<b>+${fmt(buckets[i].earned)} ${unit}</b>`; tip.style.left = (x/W*100)+'%'; tip.style.top = (y/H*r.height)+'px'; tip.style.opacity = 1; };\n  el.onmouseleave = () => { tip.style.opacity = 0; vl.setAttribute('opacity',0); pt.setAttribute('opacity',0); };\n}\nfunction fmtShort(v){ const c = state.compact; state.compact = true; const s = fmt(v); state.compact = c; return s; }\n\nconst HERO_SVG = `<svg viewBox=\"0 0 360 260\" fill=\"currentColor\" aria-hidden=\"true\"><rect x=\"20\" y=\"150\" width=\"82\" height=\"100\" rx=\"6\"/><rect x=\"128\" y=\"110\" width=\"82\" height=\"140\" rx=\"6\"/><rect x=\"236\" y=\"50\" width=\"82\" height=\"200\" rx=\"6\"/><path d=\"M12 120 C110 122 210 104 306 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"22\" stroke-linecap=\"round\"/><polygon points=\"354,0 288,18 338,66\"/></svg>`;\nconst BOX_SVG = `<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#5eead4\" stroke-width=\"2\" stroke-linejoin=\"round\"><path d=\"M3 7.5 12 3l9 4.5v9L12 21l-9-4.5z\"/><path d=\"M3 7.5l9 4.5 9-4.5M12 12v9\"/></svg>`;\nconst USERS_SVG = `<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"9\" cy=\"8\" r=\"3.5\"/><path d=\"M2.5 20c.6-3.6 3.2-5.5 6.5-5.5s5.9 1.9 6.5 5.5\"/></svg>`;\nconst NAMES = { mojo:'Mojo', candy:'Candy' }, COLORS = { mojo:'#a78bfa', candy:'#fbbf24' };\nconst RL = { 60:'hour', 360:'6 hours', 1440:'24 hours' };\n\nfunction head(title, sub){ return `<header class=\"top\"><div><h1>${title}</h1><p class=\"sub\" id=\"sub\">${sub||'&nbsp;'}</p></div><div class=\"live\"><span class=\"pulse\"></span><span id=\"liveTxt\">Live</span></div></header><div class=\"msg\" id=\"msg\"></div>`; }\n\n/* ---------- shells ---------- */\nfunction shell(){\n  const m = $('#main'), t = state.tab;\n  m.dataset.tab = t; m.style.animation = 'none'; void m.offsetWidth; m.style.animation = '';\n  document.querySelectorAll('#nav button').forEach(b => b.classList.toggle('active', b.dataset.tab === t));\n  if (t === 'overview') {\n    m.innerHTML = head('Overview','Everything across your accounts at a glance') + `\n      <div class=\"stats\">\n        <div class=\"card stat\"><div class=\"chip\">${USERS_SVG}</div><span class=\"l\">Online accounts</span><span class=\"v\" id=\"s-on\">0</span><span class=\"d\" id=\"s-on-d\">&nbsp;</span></div>\n        <div class=\"card stat\"><div class=\"chip\"><img src=\"/icon-mojo.png\" alt=\"\"></div><span class=\"l\">Total Mojo</span><span class=\"v\" id=\"s-mojo\">0</span><span class=\"d\" id=\"s-mojo-d\">&nbsp;</span></div>\n        <div class=\"card stat\"><div class=\"chip\"><img src=\"/icon-candy.png\" alt=\"\"></div><span class=\"l\">Total Candy</span><span class=\"v\" id=\"s-candy\">0</span><span class=\"d\" id=\"s-candy-d\">&nbsp;</span></div>\n        <div class=\"card stat\"><div class=\"chip\">${BOX_SVG}</div><span class=\"l\">Inventory items</span><span class=\"v\" id=\"s-items\">0</span><span class=\"d\" id=\"s-items-d\">&nbsp;</span></div>\n      </div>\n      <div class=\"two\">\n        <div class=\"card\" style=\"--a1:#c4b5fd\"><h3>Mojo earned</h3><div class=\"earnhead\"><span class=\"big\" id=\"o-mojo\">+0</span><span class=\"lbl\">earnt this hour</span></div><div class=\"chart\" id=\"o-mojo-c\"></div></div>\n        <div class=\"card\" style=\"--a1:#fde68a\"><h3>Candy earned</h3><div class=\"earnhead\"><span class=\"big\" id=\"o-candy\">+0</span><span class=\"lbl\">earnt this hour</span></div><div class=\"chart\" id=\"o-candy-c\"></div></div>\n      </div>\n      <div class=\"card\"><h3>Accounts <button class=\"btn ghost sm\" data-go=\"accounts\">View all</button></h3><div class=\"lb\" id=\"o-list\"></div></div>`;\n  } else if (t === 'mojo' || t === 'candy') {\n    m.innerHTML = head(NAMES[t], `Track ${NAMES[t].toLowerCase()} per account and what you earn over time`) + `\n      <div class=\"card hero\"><div class=\"hero-top\">\n        <div class=\"hero-l\"><div class=\"hero-ic\">${HERO_SVG}</div><div><div class=\"big\" id=\"h-big\">+0</div><div class=\"lbl\" id=\"h-lbl\">earnt this hour</div></div></div>\n        <div class=\"ctl\"><select id=\"h-user\"><option value=\"all\">All accounts</option></select><div class=\"pills\" id=\"h-r\"></div></div></div>\n        <div class=\"minis\"><div><small>Total ${NAMES[t].toLowerCase()}</small><b id=\"h-total\">0</b></div><div><small>Best account</small><b id=\"h-best\">\u2014</b></div><div><small>Online</small><b id=\"h-on\">0</b></div></div>\n        <div class=\"chart\" id=\"h-chart\"></div></div>\n      <div class=\"card\"><h3>Accounts</h3><div class=\"lb\" id=\"h-list\"></div></div>`;\n    pills();\n    $('#h-user').onchange = e => { state.chartUser = e.target.value; refresh(true); };\n  } else if (t === 'inventory') {\n    m.innerHTML = head('Inventory','Everything your accounts are holding') + `\n      <div class=\"stats\" style=\"grid-template-columns:repeat(3,1fr)\">\n        <div class=\"card stat\"><span class=\"l\">Item types</span><span class=\"v\" id=\"i-types\">0</span></div>\n        <div class=\"card stat\"><span class=\"l\">Total quantity</span><span class=\"v\" id=\"i-total\">0</span></div>\n        <div class=\"card stat\"><span class=\"l\">Most held</span><span class=\"v\" id=\"i-top\" style=\"font-size:22px\">\u2014</span></div></div>\n      <div class=\"tool\"><input class=\"fld\" id=\"q\" placeholder=\"Search items...\" value=\"${esc(state.q)}\"><select id=\"invUser\"><option value=\"all\">All accounts</option></select>\n        <select id=\"sort\"><option value=\"qty\">Most held</option><option value=\"name\">A to Z</option></select></div>\n      <div class=\"grid\" id=\"grid\"></div>`;\n    $('#sort').value = state.sort;\n    $('#q').oninput = e => { state.q = e.target.value; drawInv(); };\n    $('#sort').onchange = e => { state.sort = e.target.value; drawInv(); };\n    $('#invUser').onchange = e => { state.invUser = e.target.value; refresh(true); };\n  } else if (t === 'accounts') {\n    m.innerHTML = head('Accounts','Every account running the loader') + `<div class=\"card\" style=\"overflow-x:auto\"><table><thead><tr><th>Account</th><th>Status</th><th class=\"r\">Level</th><th class=\"r\">Mojo</th><th class=\"r\">Candy</th><th class=\"r\">Mojo / hr</th><th class=\"r\">Candy / hr</th><th class=\"r\">Items</th><th></th></tr></thead><tbody id=\"a-body\"></tbody></table></div>`;\n  } else {\n    m.innerHTML = head('Settings','Connection, display and loader') + `<div class=\"set\">\n      <div class=\"card\"><h3>Access key</h3><p>The same <code>ACCESS_KEY</code> as your API. It is stored only in this browser.</p>\n        <div class=\"line\"><input class=\"fld\" type=\"password\" id=\"key\" placeholder=\"Paste your key\" value=\"${esc(state.key)}\"><button class=\"btn\" id=\"saveKey\">Save &amp; test</button></div><p id=\"keyStat\" style=\"margin:12px 0 0\"></p></div>\n      <div class=\"card\"><h3>Loader</h3><p>Run this in your executor on every account you want to track. Clicking <b>Copy loader</b> in the sidebar copies the same line.</p>\n        <code class=\"box\" id=\"ldr\"></code><button class=\"btn ghost\" id=\"ldrCopy\">Copy</button></div>\n      <div class=\"card\"><h3>Display</h3>\n        <div class=\"opt\"><span>Hide offline accounts<small>Only show accounts that are currently online</small></span><label class=\"sw\"><input type=\"checkbox\" id=\"hideOff\" ${state.hideOffline?'checked':''}><i></i></label></div>\n        <div class=\"opt\"><span>Compact numbers<small>Show 15.9K instead of 15,900</small></span><label class=\"sw\"><input type=\"checkbox\" id=\"compact\" ${state.compact?'checked':''}><i></i></label></div>\n        <div class=\"opt\"><span>Refresh speed<small>How often the dashboard asks the API for new stats</small></span><select id=\"int\"><option value=\"2\">2 seconds</option><option value=\"5\">5 seconds</option><option value=\"10\">10 seconds</option><option value=\"30\">30 seconds</option></select></div></div>\n      <div class=\"card\"><h3>Connection</h3><p style=\"margin:0\">API: <code>${esc(CFG.apiUrl || 'not set')}</code></p></div></div>`;\n    $('#int').value = String(state.interval);\n    $('#saveKey').onclick = () => { state.key = $('#key').value.trim(); ls.set('bb_key', state.key); refresh(true).then(() => toast('Key saved')); };\n    $('#hideOff').onchange = e => { state.hideOffline = e.target.checked; ls.set('bb_hide', e.target.checked?'1':'0'); };\n    $('#compact').onchange = e => { state.compact = e.target.checked; ls.set('bb_compact', e.target.checked?'1':'0'); };\n    $('#int').onchange = e => { state.interval = +e.target.value; ls.set('bb_int', e.target.value); start(); };\n    $('#ldrCopy').onclick = copyLoader; drawLoader();\n  }\n  m.querySelectorAll('[data-go]').forEach(b => b.onclick = () => setTab(b.dataset.go));\n}\nfunction pills(){ const el = $('#h-r'); if (!el) return;\n  el.innerHTML = [60,360,1440].map(r => `<button data-r=\"${r}\" class=\"${state.range===r?'active':''}\">${r===60?'1h':r===360?'6h':'24h'}</button>`).join('');\n  el.querySelectorAll('button').forEach(b => b.onclick = () => { state.range = +b.dataset.r; pills(); refresh(true); }); }\nfunction loaderLine(masked){ const base = (CFG.apiUrl||'').replace(/\\/+$/,''); return `loadstring(game:HttpGet(\"${base}/loader.lua?key=${masked ? '\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022' : encodeURIComponent(state.key)}\"))()`; }\nfunction drawLoader(){ const el = $('#ldr'); if (el) el.textContent = state.key ? loaderLine(true) : 'Save your access key first'; }\n\n/* ---------- renderers ---------- */\nfunction visible(){ return state.hideOffline ? state.accounts.filter(a => a.online) : state.accounts; }\nfunction board(el, metric, list){\n  if (!list.length) { el.innerHTML = `<div class=\"empty\">No accounts yet. Click <b>Copy loader</b> and run it in Roblox.</div>`; return; }\n  const sorted = list.slice().sort((a,b) => (b.online-a.online) || ((b[metric]||0)-(a[metric]||0)));\n  const max = Math.max(1, ...sorted.map(a => a[metric]||0));\n  el.innerHTML = sorted.map(a => `<div class=\"lrow ${a.online?'':'off'}\">${avatar(a)}\n    <div class=\"nm\"><b>${esc(a.user)}<span class=\"lvl\">Lv ${a.level ?? '?'}</span></b><small>${a.online?'Online':'Seen '+ago(a.lastSeen)}</small></div>\n    <div class=\"bar\"><i style=\"width:${(a[metric]||0)/max*100}%\"></i></div><div class=\"val\">${fmt(a[metric])}</div><div class=\"chip2\">+${fmt(a[metric+'Hour'])}/hr</div></div>`).join('');\n}\nfunction fillSelect(sel, cur){ const el = $(sel); if (!el) return; const names = state.accounts.map(a => a.user);\n  if (el.options.length-1 !== names.length) { el.innerHTML = `<option value=\"all\">All accounts</option>` + names.map(n => `<option value=\"${esc(n)}\">${esc(n)}</option>`).join(''); el.value = names.includes(cur) ? cur : 'all'; } }\n\nfunction drawInv(){ const el = $('#grid'); if (!el) return; const q = state.q.toLowerCase();\n  let items = (drawInv.data||[]).filter(i => i.name.toLowerCase().includes(q));\n  items.sort(state.sort === 'name' ? (a,b) => a.name.localeCompare(b.name) : (a,b) => b.total-a.total);\n  const all = drawInv.data || [];\n  setNum('#i-types', all.length, v => String(Math.round(v))); setNum('#i-total', all.reduce((s,i)=>s+i.total,0));\n  $('#i-top').textContent = all.length ? all.slice().sort((a,b)=>b.total-a.total)[0].name : '\u2014';\n  $('#sub').textContent = items.length === all.length ? 'Everything your accounts are holding' : `Showing ${items.length} of ${all.length} items`;\n  if (!items.length) { el.innerHTML = `<div class=\"empty\" style=\"grid-column:1/-1\">No items found.</div>`; return; }\n  el.innerHTML = items.map(i => {\n    const by = state.invUser === 'all' && i.accounts.length > 1 ? i.accounts.slice(0,3).map(a => `<span>${esc(a.user)} \u00d7${fmt(a.amount)}</span>`).join('') + (i.accounts.length>3?`<span>+${i.accounts.length-3}</span>`:'') : '';\n    const img = i.imageId ? `<img loading=\"lazy\" src=\"/api/thumb/${i.imageId}\" alt=\"\" onerror=\"this.replaceWith(Object.assign(document.createElement('span'),{className:'ph',textContent:'${esc(i.name[0]||'?').replace(/'/g,'')}'}))\">` : `<span class=\"ph\">${esc((i.name[0]||'?').toUpperCase())}</span>`;\n    return `<div class=\"item\"><div class=\"ico\">${img}</div><div class=\"n\">${esc(i.name)}</div><div class=\"q\">\u00d7${fmt(i.total)}</div>${by?`<div class=\"chips\">${by}</div>`:''}</div>`; }).join('');\n}\n\nasync function refresh(force){\n  if (busy && !force) return; busy = true;\n  try {\n    if (!state.key) { msg('Enter your access key in Settings to connect.'); setStatus(null); return; }\n    const a = await api('/api/accounts'); state.accounts = a.accounts; msg('');\n    const on = state.accounts.filter(x => x.online).length; setStatus(on); $('#tagAcc').textContent = state.accounts.length;\n    const lt = $('#liveTxt'); if (lt) lt.textContent = 'Live \u00b7 ' + new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});\n    const t = state.tab, A = state.accounts;\n    if (t === 'overview') {\n      const sum = k => A.reduce((s,x) => s + (x[k]||0), 0);\n      setNum('#s-on', on, v => String(Math.round(v))); $('#s-on-d').textContent = `of ${A.length} account${A.length===1?'':'s'}`;\n      setNum('#s-mojo', sum('mojo')); $('#s-mojo-d').innerHTML = `<b>+${fmt(sum('mojoHour'))}</b> this hour`;\n      setNum('#s-candy', sum('candy')); $('#s-candy-d').innerHTML = `<b>+${fmt(sum('candyHour'))}</b> this hour`;\n      setNum('#s-items', sum('items')); $('#s-items-d').textContent = `${Math.max(0,...A.map(x=>x.kinds||0))} item types`;\n      const [cm, cc] = await Promise.all([api('/api/chart?metric=mojo&range=60'), api('/api/chart?metric=candy&range=60')]);\n      setNum('#o-mojo', cm.total, v => '+' + fmt(v)); setNum('#o-candy', cc.total, v => '+' + fmt(v));\n      chart('#o-mojo-c', cm.buckets, COLORS.mojo, 'Mojo', 'om'); chart('#o-candy-c', cc.buckets, COLORS.candy, 'Candy', 'oc');\n      const el = $('#o-list'), list = visible().slice().sort((x,y) => (y.online-x.online)||(y.mojo||0)-(x.mojo||0)).slice(0,5);\n      el.innerHTML = list.length ? list.map(x => `<div class=\"lrow ${x.online?'':'off'}\" style=\"grid-template-columns:40px minmax(120px,1.4fr) 1fr 1fr\">${avatar(x)}<div class=\"nm\"><b>${esc(x.user)}<span class=\"lvl\">Lv ${x.level ?? '?'}</span></b><small>${x.online?'Online':'Seen '+ago(x.lastSeen)}</small></div><div class=\"val\" style=\"text-align:left\">${fmt(x.mojo)} <small style=\"color:var(--mute);font-weight:500\">mojo</small></div><div class=\"val\" style=\"text-align:left\">${fmt(x.candy)} <small style=\"color:var(--mute);font-weight:500\">candy</small></div></div>`).join('') : `<div class=\"empty\">No accounts yet. Click <b>Copy loader</b> and run it in Roblox.</div>`;\n    } else if (t === 'mojo' || t === 'candy') {\n      fillSelect('#h-user', state.chartUser);\n      const c = await api(`/api/chart?metric=${t}&range=${state.range}&user=${encodeURIComponent(state.chartUser)}`);\n      setNum('#h-big', c.total, v => '+' + fmt(v)); $('#h-lbl').textContent = 'earnt this ' + RL[state.range];\n      chart('#h-chart', c.buckets, COLORS[t], NAMES[t], 'h');\n      const best = A.slice().sort((x,y) => (y[t]||0)-(x[t]||0))[0];\n      setNum('#h-total', A.reduce((s,x)=>s+(x[t]||0),0)); $('#h-best').textContent = best ? best.user : '\u2014'; setNum('#h-on', on, v => String(Math.round(v)));\n      $('#sub').textContent = `Track ${NAMES[t].toLowerCase()} per account and what you earn over time`;\n      board($('#h-list'), t, visible());\n    } else if (t === 'inventory') {\n      fillSelect('#invUser', state.invUser);\n      drawInv.data = (await api('/api/inventory?user=' + encodeURIComponent(state.invUser))).items; drawInv();\n    } else if (t === 'accounts') {\n      const L = visible().slice().sort((x,y) => (y.online-x.online)||x.user.localeCompare(y.user));\n      $('#sub').textContent = `${on} online \u00b7 ${A.length} total`;\n      $('#a-body').innerHTML = L.length ? L.map(x => `<tr><td><div class=\"who\">${avatar(x)}<div class=\"nm\"><b>${esc(x.user)}</b><small>${esc(x.displayName||'')}</small></div></div></td>\n        <td><span class=\"pill ${x.online?'on':''}\"><span class=\"dot ${x.online?'on':''}\" style=\"width:7px;height:7px\"></span>${x.online?'Online':ago(x.lastSeen)}</span></td>\n        <td class=\"r\">${x.level ?? '\u2014'}</td><td class=\"r\">${fmt(x.mojo)}</td><td class=\"r\">${fmt(x.candy)}</td><td class=\"r ok\">+${fmt(x.mojoHour)}</td><td class=\"r ok\">+${fmt(x.candyHour)}</td><td class=\"r\">${fmt(x.items)}</td>\n        <td class=\"r\"><button class=\"btn ghost sm red\" data-del=\"${esc(x.user)}\">Remove</button></td></tr>`).join('') : `<tr><td colspan=\"9\" class=\"empty\">No accounts yet.</td></tr>`;\n      document.querySelectorAll('[data-del]').forEach(b => b.onclick = async () => { if (!confirm('Remove ' + b.dataset.del + '?')) return;\n        try { await api('/api/account/' + encodeURIComponent(b.dataset.del), { method:'DELETE' }); refresh(true); } catch(e) { toast('Failed'); } });\n    } else { const ks = $('#keyStat'); if (ks) ks.innerHTML = `<span class=\"ok\">\u25cf Connected</span> \u00b7 ${A.length} account${A.length===1?'':'s'} reporting`; drawLoader(); }\n  } catch (e) {\n    setStatus(null);\n    if (e.message === 'auth') { msg('Wrong access key. Check it in Settings.'); const ks=$('#keyStat'); if (ks) ks.innerHTML='<span class=\"bad\">\u25cf Wrong key</span>'; }\n    else msg('Cannot reach the API. Check API_URL on the Worker and that the API is running.');\n  } finally { busy = false; }\n}\nfunction setStatus(on){ const d = $('#sdot'), t = $('#stxt'); d.classList.toggle('on', on != null && on > 0); t.textContent = on == null ? 'Not connected' : `${on} account${on===1?'':'s'} online`; }\nfunction start(){ clearInterval(timer); timer = setInterval(refresh, Math.max(2, state.interval) * 1000); }\nfunction setTab(t){ state.tab = t; ls.set('bb_tab', t); shell(); refresh(true); }\ndocument.querySelectorAll('#nav button').forEach(b => b.onclick = () => setTab(b.dataset.tab));\n\nasync function copyLoader(){\n  if (!state.key) { toast('Add your key in Settings first'); setTab('settings'); return; }\n  if (!CFG.apiUrl) { toast('API_URL not set in the Worker'); return; }\n  const s = loaderLine(false);\n  try { await navigator.clipboard.writeText(s); }\n  catch (e) { const ta = document.createElement('textarea'); ta.value = s; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch(_) {} ta.remove(); }\n  toast('Loader copied to clipboard');\n}\n$('#copyLoader').onclick = copyLoader;\nshell(); refresh(true); start();\n})();\n</script>\n</body>\n</html>\n";
const ICON_MOJO = "";
const ICON_CANDY = "";

function png(b64) {
  const bin = atob(b64), u = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
  return new Response(u, { headers: { 'content-type': 'image/png', 'cache-control': 'public, max-age=86400' } });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const apiUrl = String(env.API_URL || '').replace(/\/+$/, '');

    if (url.pathname === '/' || url.pathname === '/index.html') {
      const page = HTML.replace('/*CFG*/{}', () => JSON.stringify({ apiUrl }).replace(/</g, '\\u003c'));
      return new Response(page, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' } });
    }
    if (url.pathname === '/icon-mojo.png') return png(ICON_MOJO);
    if (url.pathname === '/icon-candy.png') return png(ICON_CANDY);

    if (url.pathname.startsWith('/api/') || url.pathname === '/loader.lua') {
      if (!apiUrl) return new Response('API_URL is not set on this Worker', { status: 500 });
      const headers = new Headers(request.headers);
      headers.delete('host');
      const upstream = await fetch(apiUrl + url.pathname + url.search, {
        method: request.method,
        headers,
        body: ['GET', 'HEAD'].includes(request.method) ? undefined : request.body,
        redirect: 'manual',
      });
      return new Response(upstream.body, upstream);
    }
    return new Response('Not found', { status: 404 });
  },
};
